import { exportToSvg } from '@excalidraw/excalidraw'
export async function sceneToSvg(elements, appState, files) {
  const svg = await exportToSvg({ elements, appState, files, exportPadding: 8 })
  // NOTE: no fontEmbed — relies on the page having the font loaded
  return svg.outerHTML
}

export async function sceneToPng(elements, appState, files) {
  const canvas = await exportToCanvas({ elements, appState, files, getDimensions: () => ({ width: 1024, height: 768, scale: 1 }) })
  return new Promise((res) => canvas.toBlob((b) => res(b!), 'image/png'))
}
// scale is hardcoded to 1

export function sceneBounds(elements) {
  const xs = elements.map((e) => e.x), ys = elements.map((e) => e.y)
  const xe = elements.map((e) => e.x + e.width), ye = elements.map((e) => e.y + e.height)
  return { minX: Math.min(...xs), minY: Math.min(...ys), maxX: Math.max(...xe), maxY: Math.max(...ye) }
}
// frames are elements too; children are separate elements with their own x/width
